/* 客户端本地数据（datapack.v1）：手动下载的数据包存在浏览器 IndexedDB，页面优先读本地，命中就不访问服务器。
   - 主数据包：GET /api/platform/datapack（gzip JSON），条目以规范化请求路径为键（与 deploy/datapack.py 的 canonical 相同）。
   - 附加包：GET /api/platform/datapack/extra/{id}，体积大的部分按需手动下载：tm:<模式族>（实验响应 3D 页）、
     cards:<模型>（单元卡）。条目逐条存进 IndexedDB（x|<路径>），读取时按需取出，不常驻内存。
   - 在线网页版的按需缓存：实验响应的合并统计与规律分析第一次在线读取后存进本地（od|<主包版本>|<路径>）。
   浏览器禁用 IndexedDB 时退化为只在内存里保存（关闭页面即失效）。 */

import {consumeResearchStream} from './researchStream.js';
const DB_NAME = 'ai2050-data';
const STORE = 'kv';
const ON_DEMAND = [/^\/api\/agg\/[^/]+\/v2$/, /^\/api\/analysis\/[^/]+$/];

const state = { ready: false, version: null, createdAt: null, bytes: 0, entries: new Map(), extras: {}, tick: 0 };
const listeners = new Set();
const memory = new Map();          // IndexedDB 不可用时的退路
let dbPromise = null;
let initPromise = null;

function emit() {
  state.tick += 1;
  listeners.forEach(fn => fn());
}

export function subscribe(fn) {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

export function storeTick() {
  return state.tick;
}

export function packInfo() {
  return { ready: state.ready, version: state.version, createdAt: state.createdAt, bytes: state.bytes, n: state.entries.size,
           extras: state.extras, tick: state.tick };
}

/* 规范化请求路径：路径 + 按键排序、解码后的查询参数（与服务端相同）。 */
export function canonical(path) {
  const i = path.indexOf('?');
  if (i < 0) return path;
  const params = [...new URLSearchParams(path.slice(i + 1)).entries()];
  params.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0)));
  return path.slice(0, i) + (params.length ? '?' + params.map(([k, v]) => `${k}=${v}`).join('&') : '');
}

/* 一条请求应在哪个附加包里（与 deploy/datapack.py 的 pack_hint 相同）。 */
export function packHint(path) {
  const [p, q = ''] = path.split('?');
  if (p.startsWith('/api/research-library/artifacts') || ['/api/research-library/graph','/api/research-library/fragments','/api/research-library/workpackages','/api/research-library/catalog','/api/traces/research-space'].includes(p)) return 'research-library';
  const m = /^\/api\/(?:agg\/([^/]+)\/v2|analysis\/([^/]+))$/.exec(p);
  if (m) return `tm:${decodeURIComponent(m[1] || m[2])}`;
  if (p === '/api/neurons/unit' || p === '/api/neurons/layer') {
    const mk = new URLSearchParams(q).get('model_key');
    return mk ? `cards:${mk}` : null;
  }
  if (p === '/api/neurons/circuit') {
    const mk = new URLSearchParams(q).get('model_key');
    return mk ? `circuit:${mk}` : null;
  }
  return null;
}

function openDb() {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise(resolve => {
    try {
      const req = indexedDB.open(DB_NAME, 1);
      req.onupgradeneeded = () => req.result.createObjectStore(STORE);
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve(null);
    } catch {
      resolve(null);
    }
  });
  return dbPromise;
}

async function idb(op, key, value) {
  const db = await openDb();
  if (!db) {
    if (op === 'get') return memory.get(key);
    if (op === 'put') memory.set(key, value);
    else if (op === 'clear') memory.clear();
    else memory.delete(key);
    return true;
  }
  return new Promise(resolve => {
    try {
      const tx = db.transaction(STORE, op === 'get' ? 'readonly' : 'readwrite');
      const st = tx.objectStore(STORE);
      const req = op === 'get' ? st.get(key) : op === 'put' ? st.put(value, key) : op === 'clear' ? st.clear() : st.delete(key);
      req.onsuccess = () => resolve(op === 'get' ? req.result : true);
      req.onerror = () => resolve(undefined);
    } catch {
      resolve(undefined);
    }
  });
}

/* 一个事务里写入多条（附加包可能有上千条）。 */
async function idbPutMany(pairs, deleteKeys = []) {
  const db = await openDb();
  if (!db) {
    deleteKeys.forEach(k => memory.delete(k));
    pairs.forEach(([k, v]) => memory.set(k, v));
    return;
  }
  await new Promise(resolve => {
    try {
      const tx = db.transaction(STORE, 'readwrite');
      const st = tx.objectStore(STORE);
      deleteKeys.forEach(k => st.delete(k));
      pairs.forEach(([k, v]) => st.put(v, k));
      tx.oncomplete = () => resolve();
      tx.onerror = () => resolve();
      tx.onabort = () => resolve();
    } catch {
      resolve();
    }
  });
}

/* 启动时从本地载入主数据包与附加包清单（只做一次）。 */
export function initDataStore() {
  if (!initPromise) {
    initPromise = (async () => {
      const pack = await idb('get', 'pack');
      if (pack?.version && pack.entries) {
        state.version = pack.version;
        state.createdAt = pack.created_at;
        state.bytes = pack.bytes || 0;
        state.entries = new Map(Object.entries(pack.entries));
      }
      state.extras = (await idb('get', 'xmeta')) || {};
      state.ready = true;
      emit();
    })();
  }
  return initPromise;
}

export function getLocal(path) {
  return state.entries.get(canonical(path));
}

/* 附加包里的条目（异步，从 IndexedDB 取）；没有时返回 undefined。 */
export async function getExtraEntry(path) {
  const id = packHint(path);
  if (!id || !state.extras[id]) return undefined;
  return idb('get', `${state.extras[id].key_prefix||'x|'}${canonical(path)}`);
}

export function isOnDemand(path) {
  const p = path.split('?')[0];
  return ON_DEMAND.some(re => re.test(p));
}

export async function getOnDemand(path) {
  if (!state.version) return undefined;
  return idb('get', `od|${state.version}|${canonical(path)}`);
}

export async function putOnDemand(path, data) {
  if (!state.version || data?.pending) return;
  await idb('put', `od|${state.version}|${canonical(path)}`, data);
}

/* 下载一个 gzip JSON 数据包并解析；onProgress(已下载字节, 总字节)。 */
async function fetchPack(url, onProgress) {
  const response = await fetch(url, { cache: 'no-store' });
  if (!response.ok) {
    const body = await response.json().catch(() => ({}));
    throw new Error(body.detail || `HTTP ${response.status}`);
  }
  const total = Number(response.headers.get('content-length')) || 0;
  const reader = response.body.getReader();
  const chunks = [];
  let got = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value);
    got += value.length;
    onProgress?.(got, total);
  }
  const blob = new Blob(chunks);
  const text = await new Response(blob.stream().pipeThrough(new DecompressionStream('gzip'))).text();
  return { doc: JSON.parse(text), bytes: got };
}

/* 下载并保存主数据包。 */
export async function downloadDataPack(apiBase, onProgress) {
  const { doc, bytes } = await fetchPack(`${apiBase}/api/platform/datapack`, onProgress);
  if (doc.schema !== 'datapack.v1') throw new Error('不是 datapack.v1 数据包');
  const old = state.version;
  await idb('put', 'pack', { version: doc.version, created_at: doc.created_at, bytes, entries: doc.entries });
  state.version = doc.version;
  state.createdAt = doc.created_at;
  state.bytes = bytes;
  state.entries = new Map(Object.entries(doc.entries));
  if (old && old !== doc.version) clearOldOnDemand(doc.version);
  emit();
  return packInfo();
}

/* 下载并保存一个附加包（替换同一个包的旧条目）。 */
export async function downloadExtra(apiBase, id, onProgress) {
  if(id==='research-library')return downloadResearchStream(apiBase,id,onProgress);
  const { doc, bytes } = await fetchPack(`${apiBase}/api/platform/datapack/extra/${encodeURIComponent(id)}`, onProgress);
  if (doc.schema !== 'datapack_extra.v1' || doc.id !== id) throw new Error('不是对应的附加包');
  const oldKeys = (await idb('get', `xkeys|${id}`)) || [];
  const keys = Object.keys(doc.entries).map(k => `x|${k}`);
  await idbPutMany([...Object.entries(doc.entries).map(([k, v]) => [`x|${k}`, v]), [`xkeys|${id}`, keys]],
    oldKeys.filter(k => !keys.includes(k)));
  state.extras = { ...state.extras, [id]: { version: doc.version, created_at: doc.created_at, bytes, n: keys.length } };
  await idb('put', 'xmeta', state.extras);
  emit();
  return state.extras[id];
}

async function downloadResearchStream(apiBase,id,onProgress){
  const db=await openDb();if(!db)throw Error('研究全版本附加包需要可用的浏览器本地数据库；当前仍可在线浏览。');
  const response=await fetch(`${apiBase}/api/platform/datapack/extra/${encodeURIComponent(id)}?format=ndjson`,{cache:'no-store'});
  if(!response.ok||!response.headers.get('Content-Type')?.startsWith('application/x-ndjson+gzip'))throw Error('中心暂不支持流式研究包，请更新中心服务后重试。');
  let got=0;const total=Number(response.headers.get('Content-Length'))||0,keys=[],prefix=`xv|${id}|${crypto.randomUUID()}|`;
  const progress=new TransformStream({transform(chunk,controller){got+=chunk.byteLength;onProgress?.(got,total);controller.enqueue(chunk)}});
  const stream=response.body.pipeThrough(progress).pipeThrough(new DecompressionStream('gzip')).pipeThrough(new TextDecoderStream());
  const transaction=(writes,deletes=[])=>new Promise((resolve,reject)=>{
    const tx=db.transaction(STORE,'readwrite'),s=tx.objectStore(STORE);
    for(const k of deletes)s.delete(k);for(const [k,v] of writes)s.put(v,k);
    tx.oncomplete=resolve;tx.onerror=()=>reject(Error('本机存储写入失败，原版本保持可用'));tx.onabort=()=>reject(Error('本机存储提交中断，原版本保持可用'));
  });
  try{
    const {header,count}=await consumeResearchStream(stream,{id,onEntry:async(path,data)=>{const key=prefix+canonical(path);if(keys.includes(key))throw Error('附加包含重复条目');keys.push(key);await transaction([[key,data]])}});
    const oldKeys=(await idb('get',`xkeys|${id}`))||[];
    const next={...state.extras,[id]:{version:header.version,created_at:header.created_at,bytes:got,n:count,key_prefix:prefix}};
    await transaction([[`xkeys|${id}`,keys],['xmeta',next]],oldKeys);
    state.extras=next;emit();return state.extras[id];
  }catch(error){await transaction([],keys).catch(()=>{});throw error}
}

async function clearOldOnDemand(keepVersion) {
  const db = await openDb();
  if (!db) return;
  try {
    const tx = db.transaction(STORE, 'readwrite');
    const req = tx.objectStore(STORE).openCursor();
    req.onsuccess = () => {
      const cur = req.result;
      if (!cur) return;
      if (String(cur.key).startsWith('od|') && !String(cur.key).startsWith(`od|${keepVersion}|`)) cur.delete();
      cur.continue();
    };
  } catch { /* 清理失败不影响使用 */ }
}

export async function clearDataStore() {
  await idb('clear');
  state.version = null;
  state.createdAt = null;
  state.bytes = 0;
  state.entries = new Map();
  state.extras = {};
  emit();
}

/* One bounded JSON entry at a time; completion is required before publishing a cache. */
export async function consumeResearchStream(stream,{id,onEntry=async()=>{},onHeader=async()=>{}}={}){
  const reader=stream.getReader();let buffer='',header=null,footer=null,count=0;
  async function line(text){
    if(!text.trim())return;
    const value=JSON.parse(text);
    if(!header){if(value.schema!=='datapack_extra_stream.v1'||value.id!==id||typeof value.version!=='string')throw Error('不是对应的流式附加包');header=value;await onHeader(value);return}
    if(footer)throw Error('附加包完成标记之后仍有数据');
    if(value.complete===true){if(value.version!==header.version||value.n_entries!==count)throw Error('附加包计数或版本不一致');footer=value;return}
    if(typeof value.path!=='string'||!value.path.startsWith('/api/')||!Object.hasOwn(value,'data'))throw Error('附加包条目无效');
    await onEntry(value.path,value.data);count++;
  }
  try{
    while(true){const {done,value}=await reader.read();if(done)break;buffer+=value;
      let pos;while((pos=buffer.indexOf('\n'))>=0){const text=buffer.slice(0,pos);buffer=buffer.slice(pos+1);await line(text)}
      if(buffer.length>32*1024*1024)throw Error('单条附加包数据过大');
    }
    if(buffer.trim())await line(buffer);
    if(!header||!footer)throw Error('附加包不完整，继续使用原有版本');
    return {header,count};
  }catch(error){await reader.cancel().catch(()=>{});throw error}finally{reader.releaseLock()}
}

/* 本地数据状态条：显示本机数据包的版本与时间，服务器有新数据时提示手动更新。
   只读数据包模式下第一次打开（本机还没有数据包）自动下载一次主数据包（一个静态文件），之后只提示、不自动下载。
   数据包内容见 deploy/datapack.py；本地存储与读取见 rdc_fusion/dataStore.js。 */
import { useEffect, useRef, useState, useSyncExternalStore } from 'react';

import { API_BASE, OFFLINE_CLIENT, useApi } from '../app/rdc_fusion/api.js';
import './databar.css';
import { downloadDataPack, downloadExtra, packInfo, storeTick, subscribe } from '../app/rdc_fusion/dataStore.js';

function fmtTime(ts) {
  if (!ts) return '—';
  const d = new Date(ts * 1000);
  const pad = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function fmtMB(b) {
  return b ? `${(b / 2 ** 20).toFixed(1)} MB` : '';
}

export default function DataBar({ remote }) {
  useSyncExternalStore(subscribe, storeTick);
  const info = packInfo();
  const [busy, setBusy] = useState(null);
  const [err, setErr] = useState('');
  const get = async () => {
    setErr(''); setBusy({ got: 0, total: remote?.bytes || 0 });
    try {
      await downloadDataPack(API_BASE, (got, total) => setBusy({ got, total: total || remote?.bytes || 0 }));
    } catch (e) {
      setErr(e.message);
    }
    setBusy(null);
  };
  const auto = useRef(false);
  useEffect(() => {                                    // 第一次打开：自动下载主数据包（只尝试一次，失败后改为手动）
    if (!OFFLINE_CLIENT || auto.current || !info.ready || info.version || !remote?.version) return;
    auto.current = true;
    window.setTimeout(get, 0);                         // 不在副作用里同步改状态；只触发一次（auto 守卫）
  });
  if (!info.ready) return null;
  const fresh = info.version && remote?.version && info.version === remote.version;
  const label = busy ? `下载中 ${busy.total ? Math.round((100 * busy.got) / busy.total) : 0}%`
    : !info.version ? `下载数据${remote?.bytes ? `（${fmtMB(remote.bytes)}）` : ''}`
      : `更新数据${remote?.bytes ? `（${fmtMB(remote.bytes)}）` : ''}`;
  return (
    <div className={'op-databar' + (!info.version ? ' none' : fresh ? ' fresh' : ' stale')}
         title={OFFLINE_CLIENT ? '页面只读取本机保存的数据包，使用中不连接服务器；服务器有新数据时手动更新'
           : '页面优先读取本机保存的数据包，不会定时访问服务器；单元卡与管理类页面打开时在线读取'}>
      <span className="op-databar-dot" aria-hidden="true" />
      <span className="op-databar-text">
        {!info.version ? (OFFLINE_CLIENT ? (busy ? '正在下载数据包（只下载一次，之后页面都读本机数据）' : '还没有本地数据，下载后各页面显示内容') : '未下载本地数据（页面临时在线读取）')
          : fresh ? `本地数据 · ${fmtTime(info.createdAt)}`
            : remote?.version ? `本地数据 ${fmtTime(info.createdAt)} · 服务器有新数据` : `本地数据 · ${fmtTime(info.createdAt)}`}
      </span>
      {(!fresh || busy) && remote?.version && (
        <button type="button" className="op-databar-btn" onClick={get} disabled={Boolean(busy)}>{label}</button>
      )}
      {err && <span className="op-databar-err" role="alert">{err}</span>}
    </div>
  );
}

/* 全局挂载：读一次站点配置拿到服务器端数据包版本，固定显示在页面左下角（首页与工作台共用）。 */
export function DataBarHost() {
  const cfg = useApi('/api/platform/config');
  return (
    <div className="op-databar-host">
      <DataBar remote={cfg.data?.datapack} />
    </div>
  );
}

/* 附加包下载提示：离线客户端在缺少某个附加包（模式族实验响应、单元卡）时显示，下载后页面自动重读。 */
export function ExtraPackPrompt({ pack }) {
  useSyncExternalStore(subscribe, storeTick);
  const cfg = useApi('/api/platform/config');
  const [busy, setBusy] = useState(null);
  const [err, setErr] = useState('');
  if (!pack) return null;
  const meta = (cfg.data?.datapack?.extras || []).find(e => e.id === pack);
  const have = packInfo().extras[pack];
  const get = async () => {
    setErr(''); setBusy({ got: 0, total: meta?.bytes || 0 });
    try {
      await downloadExtra(API_BASE, pack, (got, total) => setBusy({ got, total: pack==='research-library'?total:(total || meta?.bytes || 0) }));
    } catch (e) {
      setErr(e.message);
    }
    setBusy(null);
  };
  const stale = Boolean(have && meta?.version && have.version !== meta.version);   // 服务器上的附加包已更新
  if (have && !stale && !busy) return null;
  return (
    <div className="op-extra">
      <span>{meta ? `${stale ? '附加包有新版本' : '需要附加包'}「${meta.label}」（${fmtMB(meta.bytes)}）` : cfg.data ? '服务器还没有生成这个附加包，稍后再试' : '读取附加包清单…'}</span>
      {meta && (
        <button type="button" className="op-databar-btn" onClick={get} disabled={Boolean(busy)}>
          {busy ? pack==='research-library'&&!busy.total?`下载并保存 ${fmtMB(busy.got)}`:`下载中 ${busy.total ? Math.round((100 * busy.got) / busy.total) : 0}%` : stale ? '更新' : '下载'}
        </button>
      )}
      {err && <span className="op-databar-err" role="alert">{err}</span>}
    </div>
  );
}

import {it,expect} from 'vitest';
